insert into public.products (slug, name, category, texture, description, details, price, compare_at, lengths, shades, stock, featured, is_new, sort) values
  ('remy-velvet-closure-wig', 'Remy Velvet Closure Wig', 'wigs', 'straight', '100% virgin Remy human hair. Silky smooth texture, full cuticle intact, tangle-free. Comes with a 5×5 HD lace closure that melts seamlessly into your skin. Perfect for beginners and professionals alike.', array['100% Virgin Human Hair', 'HD Lace Closure', 'Pre-plucked Hairline', 'Bleached Knots', '180% Density', 'Can be bleached & dyed']::text[], 85000, 110000, '[{"length": "12\"", "price": null}, {"length": "14\"", "price": null}, {"length": "16\"", "price": null}, {"length": "18\"", "price": null}, {"length": "20\"", "price": null}, {"length": "22\"", "price": null}, {"length": "24\"", "price": null}]'::jsonb, '[{"name": "Jet black", "hex": "#1a1008"}, {"name": "Dark brown", "hex": "#3d2b1f"}, {"name": "Auburn", "hex": "#6b3a2a"}, {"name": "Blonde", "hex": "#c8a96e"}, {"name": "Ash blonde", "hex": "#f5d5a0"}]'::jsonb, 15, true, false, 0),
  ('brazilian-body-wave-bundle', 'Brazilian Body Wave Bundle', 'bundles', 'body', 'Luxurious Brazilian body wave bundles with a natural bounce and flow. Double-wefted for fullness, zero shedding. The wave pattern holds beautifully whether wet or dry.', array['Brazilian Virgin Hair', 'Double Wefted', 'Zero Shedding', 'Natural Wave Pattern', 'Can be heat styled', '3 bundles recommended for full look']::text[], 65000, null, '[{"length": "10\"", "price": null}, {"length": "12\"", "price": null}, {"length": "14\"", "price": null}, {"length": "16\"", "price": null}, {"length": "18\"", "price": null}, {"length": "20\"", "price": null}]'::jsonb, '[{"name": "Natural black", "hex": "#1a1008"}, {"name": "Dark brown", "hex": "#3d2b1f"}, {"name": "Honey blonde", "hex": "#c8a96e"}]'::jsonb, 28, false, true, 1),
  ('deep-wave-frontal-wig', 'Deep Wave Frontal Wig', 'wigs', 'deep', 'Stunning deep wave pattern with a 13×6 HD lace frontal. Creates a natural-looking hairline from ear to ear. The deep, defined curls add incredible volume and drama.', array['13×6 HD Lace Frontal', 'Deep Wave Pattern', 'Ear-to-ear Coverage', 'Pre-bleached Knots', '200% Density', 'Glueless installation option']::text[], 120000, 145000, '[{"length": "14\"", "price": null}, {"length": "16\"", "price": null}, {"length": "18\"", "price": null}, {"length": "20\"", "price": null}, {"length": "22\"", "price": null}, {"length": "24\"", "price": null}, {"length": "26\"", "price": null}]'::jsonb, '[{"name": "Jet black", "hex": "#1a1008"}, {"name": "Off black", "hex": "#2b1d0e"}]'::jsonb, 8, true, false, 2),
  ('kinky-coily-4c-afro-wig', 'Kinky Coily 4C Afro Wig', 'wigs', 'coily', 'Celebrate your roots with this authentic 4C coily texture wig. Crafted from virgin African hair, it mimics the natural Afro texture perfectly. Celebrate your African heritage with unmatched realism.', array['Authentic 4C Texture', 'Virgin African Hair', 'Lace Front', 'Protective Style', 'No Heat Needed', 'Afrocentric Design']::text[], 95000, null, '[{"length": "10\"", "price": null}, {"length": "12\"", "price": null}, {"length": "14\"", "price": null}, {"length": "16\"", "price": null}]'::jsonb, '[{"name": "Natural black", "hex": "#1a1008"}, {"name": "Dark espresso", "hex": "#2b1505"}, {"name": "Reddish brown", "hex": "#6b3a2a"}]'::jsonb, 12, false, true, 3),
  ('straight-silky-bone-straight', 'Straight Silky Bone Straight', 'wigs', 'bone', 'Ultra-sleek bone straight hair with a mirror-like shine. The smoothest, silkiest straight hair we carry. Stays perfectly straight in humidity. A Baddie Strands bestseller.', array['Super Straight Texture', 'Anti-Humidity Coating', 'Mirror-like Shine', 'HD Lace', 'Beginner Friendly', 'Heat Resistant up to 230°C']::text[], 78000, 90000, '[{"length": "16\"", "price": null}, {"length": "18\"", "price": null}, {"length": "20\"", "price": null}, {"length": "22\"", "price": null}, {"length": "24\"", "price": null}, {"length": "26\"", "price": null}, {"length": "28\"", "price": null}, {"length": "30\"", "price": null}]'::jsonb, '[{"name": "Jet black", "hex": "#1a1008"}, {"name": "Platinum blonde", "hex": "#f5d5a0"}, {"name": "Ash blonde", "hex": "#e8cc99"}, {"name": "Honey blonde", "hex": "#c8a96e"}]'::jsonb, 22, true, false, 4),
  ('loose-deep-wave-clip-ins', 'Loose Deep Wave Clip-Ins', 'extensions', 'water', 'Full set of 7-piece loose deep wave clip-in extensions. Perfect for adding length and volume instantly. Easy DIY installation, no salon needed. Safe for natural hair.', array['7-Piece Full Set', 'Strong Snap Clips', 'Blend with Natural Hair', 'No Damage', 'Reusable 12+ months', 'Salon-quality finish']::text[], 45000, null, '[{"length": "14\"", "price": null}, {"length": "16\"", "price": null}, {"length": "18\"", "price": null}, {"length": "20\"", "price": null}, {"length": "22\"", "price": null}]'::jsonb, '[{"name": "Jet black", "hex": "#1a1008"}, {"name": "Dark brown", "hex": "#3d2b1f"}, {"name": "Honey blonde", "hex": "#c8a96e"}]'::jsonb, 35, false, false, 5),
  ('hd-lace-curly-bob-wig', 'HD Lace Curly Bob Wig', 'wigs', 'curly', 'Chic and modern curly bob wig with an HD lace front that disappears into your skin. The curl pattern is defined, bouncy, and holds its shape without frizz. Bold meets elegant.', array['Curly Bob Style', 'HD Undetectable Lace', 'Pre-styled', 'Frizz-resistant', 'Easy Maintenance', 'Day-to-night versatile']::text[], 72000, 85000, '[{"length": "8\"", "price": null}, {"length": "10\"", "price": null}, {"length": "12\"", "price": null}, {"length": "14\"", "price": null}]'::jsonb, '[{"name": "Jet black", "hex": "#1a1008"}, {"name": "Auburn", "hex": "#6b3a2a"}, {"name": "Honey blonde", "hex": "#c8a96e"}]'::jsonb, 10, false, true, 6),
  ('peruvian-loose-wave-bundle', 'Peruvian Loose Wave Bundle', 'bundles', 'loose', 'Peruvian loose wave bundles with the perfect blend of straight and wavy. Extremely soft texture, minimal shedding. The natural lustre of Peruvian hair is unmatched.', array['Peruvian Virgin Hair', 'Loose Wave Pattern', 'Natural Lustre', 'Low Shedding', 'Can be curled', '3-4 bundles for full head']::text[], 58000, null, '[{"length": "10\"", "price": null}, {"length": "12\"", "price": null}, {"length": "14\"", "price": null}, {"length": "16\"", "price": null}, {"length": "18\"", "price": null}, {"length": "20\"", "price": null}]'::jsonb, '[{"name": "Natural black", "hex": "#1a1008"}, {"name": "Dark brown", "hex": "#3d2b1f"}]'::jsonb, 18, false, false, 7),
  ('water-wave-glueless-wig', 'Water Wave Glueless Wig', 'wigs', 'water', 'Put it on in 60 seconds, no glue, no tape, no mess. This glueless water wave wig features an adjustable band and combs that secure it firmly. The water wave texture is playful yet polished.', array['Glueless Installation', 'Adjustable Band + Combs', '60-Second Install', 'Water Wave Texture', 'Beginner-Friendly', 'Protects Natural Hair']::text[], 88000, 105000, '[{"length": "14\"", "price": null}, {"length": "16\"", "price": null}, {"length": "18\"", "price": null}, {"length": "20\"", "price": null}, {"length": "22\"", "price": null}, {"length": "24\"", "price": null}]'::jsonb, '[{"name": "Jet black", "hex": "#1a1008"}, {"name": "Off black", "hex": "#2b1d0e"}, {"name": "Dark brown", "hex": "#3d2b1f"}]'::jsonb, 14, true, false, 8),
  ('highlight-ombre-bundle-set', 'Highlight Ombre Bundle Set', 'bundles', 'body', 'Pre-coloured ombre highlight bundles by our in-house colour artists. Beautifully blended tones from root to tip. You get the colour without the chemical damage.', array['Pre-Coloured', 'Professional Ombre Blend', 'Zero Chemical Damage to Your Hair', 'Balayage Effect', 'Instant Colour Pop', 'Heat-resistant colour']::text[], 92000, null, '[{"length": "14\"", "price": null}, {"length": "16\"", "price": null}, {"length": "18\"", "price": null}, {"length": "20\"", "price": null}]'::jsonb, '[{"name": "Honey ombre", "hex": "#c8a96e"}, {"name": "Caramel ombre", "hex": "#8b5e3c"}, {"name": "Ash ombre", "hex": "#f5d5a0"}]'::jsonb, 9, false, true, 9),
  ('ponytail-extension-wrap', 'Ponytail Extension Wrap', 'extensions', 'straight', 'Achieve the perfect sleek high pony or low bun in minutes. Wrap-around design means no clips, no damage. The drawstring system creates a tight, natural-looking base.', array['Wrap-Around Design', 'Drawstring System', 'No Clips / No Damage', 'Sleek or Curly Option', 'Match any outfit', 'Easy to style']::text[], 32000, 38000, '[{"length": "14\"", "price": null}, {"length": "18\"", "price": null}, {"length": "22\"", "price": null}, {"length": "26\"", "price": null}]'::jsonb, '[{"name": "Jet black", "hex": "#1a1008"}, {"name": "Dark brown", "hex": "#3d2b1f"}, {"name": "Honey blonde", "hex": "#c8a96e"}, {"name": "Platinum", "hex": "#f5d5a0"}]'::jsonb, 40, false, false, 10),
  ('u-part-human-hair-wig', 'U-Part Human Hair Wig', 'wigs', 'straight', 'The U-part wig blends your own natural hair through the U-shaped opening for the most undetectable, seamless look. Great for natural hair ladies who want to protect while looking polished.', array['Blends Your Natural Hair', 'Most Undetectable Look', 'U-Shaped Opening', 'Clips & Combs Included', 'Protective Style', 'No Lace Required']::text[], 68000, null, '[{"length": "14\"", "price": null}, {"length": "16\"", "price": null}, {"length": "18\"", "price": null}, {"length": "20\"", "price": null}, {"length": "22\"", "price": null}]'::jsonb, '[{"name": "Natural black", "hex": "#1a1008"}, {"name": "Off black", "hex": "#2b1d0e"}]'::jsonb, 16, false, false, 11)
on conflict (slug) do nothing;

-- Sample reviews for the home page. Replace them with real ones in
-- the admin dashboard: Website text, Reviews.
update public.settings set data = jsonb_set(data, '{reviews}', '[{"name": "Adaeze O.", "place": "Lagos, Nigeria", "stars": 5, "text": "I''ve bought from so many hair vendors and Baddie Strands is on a different level. My closure wig has been through everything — gym, beach, sweat — and it still looks brand new three months later."}, {"name": "Fatima K.", "place": "Abuja, Nigeria", "stars": 5, "text": "The quality of their bone straight wig left me speechless. People on the street thought it was my natural hair. The lace literally disappears. Nothing compares."}, {"name": "Chidinma E.", "place": "Enugu, Nigeria", "stars": 5, "text": "Fast delivery to Enugu, great packaging — the wig was wrapped so carefully. The 4C afro wig is everything I wanted. Finally a store that celebrates African texture!"}, {"name": "Blessing A.", "place": "Port Harcourt, Nigeria", "stars": 5, "text": "I ordered the deep wave wig and it arrived within 24 hours in Lagos. The communication was so smooth via WhatsApp. Best customer experience in the hair game."}, {"name": "Toyin M.", "place": "London, UK", "stars": 5, "text": "As a UK-based Nigerian, I was nervous about international delivery. They kept me updated throughout. Wig arrived beautifully, worth every penny. I''m a customer for life."}, {"name": "Precious N.", "place": "Ibadan, Nigeria", "stars": 5, "text": "I did their hair quiz and they helped me pick the perfect wig for my face shape and lifestyle. That personal touch — that''s why they''re the best in the business."}]'::jsonb, true)
  where id = 1 and not (data ? 'reviews');
